$('.mm-horizontal-list-collapsed-button').click(function() {

  $(this).html(function(i, html) {
    return /Less/.test(html) ? '<div class="fa fa-angle-down"></div> View More' : '<div class="fa fa-angle-up"></div> View Less';
  });

});
$(document).ready(function() {
  $('.mm-hidden-block-button').click(function() {
    var view_more   = $(this).data("view-more-text");
    var view_less   = $(this).data("view-less-text");
    var data_target = $(this).parent().prev();

    if ($(data_target).hasClass('in')) {
      $(data_target).collapse('hide');
      $(this).html(function(i, html) {
        return '<div class="fa fa-angle-down"></div> ' + view_more;
      });
    } else {
      $(data_target).collapse('show');
      $(this).html(function(i, html) {
        return '<div class="fa fa-angle-up"></div> ' + view_less;
      });
    }
  });
});
