(function () {
  $('.table-module').on('click', '.js-ajax-pagination li a[data-url]', function(e){
    $.ajax({
      url: $(this).attr('data-url'),
      dataType: 'script',
      success: function(responseText) {
        eval(this);
      },
      error: function(){
        return false;
      },
      complete: function(){
        if (window.location.hash && $('.table-tabs').length) {
          hash = window.location.hash;
          $("[href='"+ hash +"']").tab('show');
        }

        initializeTabs();

        $('.table-module').not('.table-module2').on('post-body.bs.table', function (e) {
          initializeTabs();
        });

        $('html, body').animate({
          scrollTop: $(".table-module").offset().top - 85
        }, 600);
      }
    });
    Mitre.Analytics.trackEvent('Table Pagination', 'Click', $(e.target).text());
    return false;
  });
})();
