  var ids = [];      // list of ids received from the api
  var next = [];     // list of ids to fetch next
  var articles = {}; // key: id, value: {path: string, visible: bool}
  var ORIGINAL_URL = location.pathname;
  let container = document.getElementById('infinite-scroll-container'); // passed in from _infinite_scroll.html.haml,
  let baseUrl = container ? `https://${container.dataset.baseUrl}` : '';
  let apiEndpoint = `${baseUrl}/api/articles/next.json`;

  InfiniteScroll.init = function(options) {
    options = options || {};
    Mitre.debug('Enabled infinite scroll');

    if (options.id) ids.push(options.id);
    if (options.api) api = options.api;
    if (options.tags) tags = options.tags;

    fetchArticleIds();
    $window.on('scroll', loadNext);
    $window.on('scroll', updateUrl);
  };

  function stop() {
    $('#next-article').remove();
    $window.off('scroll', loadNext);
    Mitre.debug('Disabled infinite scroll');
  }

  function fetchArticleIds(callback) {
    Mitre.debug('Fetching article ids');

    $.ajax({
      method: 'POST',
      url: apiEndpoint,
      data: {ids: ids, tags: tags},
      dataType: 'json',
      success: function(data) {
        if (!data.length) return stop();
        next = next.concat(data);
        if (callback) callback();
      },
      error: function(data) {
        Mitre.debug('error', data);
        stop();
      }
    });
  }

