    tables.forEach(function(table) {
      var sortBy = getDataAttr(table, 'table-sort-by');
      var sortDir = getDataAttr(table, 'table-sort-direction');

      table.addEventListener('click', function(e) {
        var target = e.target;
        var th = target.parentNode;
        if (th.tagName !== 'TH') return;

        var column = getDataAttr(th, 'column');
        var sortable = queryElementSelector(th, 'column-sortable');
        if (!sortable) return;

        // If the current columns was already selected, invert the direction of
        // sorting.
        if (column === sortBy) {
          if (sortDir === 'asc') {
            sortDir = 'desc';
          } else {
            sortDir = 'asc';
          }
        } else {
          sortBy = column;
          sortDir = 'desc';
        }

        callback(sortBy, sortDir);
      });
    });

    mobileSorts.forEach(function(liOption){
      liOption.addEventListener('click', function(e) {
        var target = e.target;
        if (target.tagName !== 'BUTTON') return;

        var sortBy = target.getAttribute("data-field");
        var sortDir = target.getAttribute("data-order");

        callback(sortBy, sortDir);
      });
    });
