  // Whenever a page is clicked, parse the page number and request a new data
  // set from the API. The page is anchored at the top.
  function paginate(_page, callback) {
    var paginations = queryScreenerSelectorAll('pagination');
    var screener = queryScreenerSelector();

    paginations.forEach(function(pagination) {
      pagination.addEventListener('click', function(e) {
        e.preventDefault();
        var target = e.target;
        var li = target.parentNode;
        if (li.tagName !== 'LI') return;
        var page = parseInt(getDataAttr(li, 'page'), 10);
        callback(page);
        screener.scrollIntoView();
      });
    });
  }

