//
// Rewrites of barchart methods to perform the redirect with the chart's hashtag
//
function bcfn_GetChart(sym2, overlay, sp, nasdaq, dow, height, width) {
  var sPath = window.location.pathname;
  var sPage = sPath.substring(sPath.lastIndexOf('/') + 1);
  if (sp.checked) {
    sp = 'true';
  } else {
    sp = '';
  }
  if (nasdaq.checked) {
    nasdaq = 'true';
  } else {
    nasdaq = '';
  }
  if (dow.checked) {
    dow = 'true';
  } else {
    dow = '';
  }
  var sHREF =
    sPage +
    '?&page=ccharts&sym=' +
    sym2 +
    '&overlay=' +
    overlay +
    '&sp=' +
    sp +
    '&nasdaq=' +
    nasdaq +
    '&dow=' +
    dow;
  if (height > 0 && width > 0) {
    sHREF += '&height=' + height + '&width=' + width;
  }
  location.href = sHREF + '#charts'; // add our hashtag
}

function saveSettings(
  name,
  studies,
  type,
  density,
  period,
  volume,
  grid,
  scale,
  size
) {
  if (name == '' || name == 'Enter a name for your settings') {
    alert('Please enter a valid name for your settings');
    return;
  }
  var bc_QueryString = new String(document.location.search).substring(1);
  var pairs = bc_QueryString.split('&');
  var newQuery = '&';
  for (var i = 0; i < pairs.length; i++) {
    var tmp = pairs[i].split('=');
    if (
      tmp[0] != 'mode' &&
      tmp[0] != 'setting' &&
      tmp[0] != 'studies' &&
      tmp[0] != 'type' &&
      tmp[0] != 'density' &&
      tmp[0] != 'a' &&
      tmp[0] != 'volume' &&
      tmp[0] != 'grid' &&
      tmp[0] != 'scale' &&
      tmp[0] != 'size'
    )
      newQuery += pairs[i] + '&';
  }
  window.location =
    '?studies=' +
    studies +
    '&type=' +
    type +
    '&density=' +
    density +
    '&a=' +
    period +
    '&volume=' +
    volume +
    '&grid=' +
    grid +
    '&scale=' +
    scale +
    '&scale=' +
    scale +
    '&size=' +
    size +
    '&setting=' +
    name +
    '&mode=save&' +
    newQuery +
    '#charts';
}

function makeDefaultSettings() {
  var bc_QueryString = new String(document.location.search).substring(1);
  var pairs = bc_QueryString.split('&');
  var newQuery = '&';
  for (var i = 0; i < pairs.length; i++) {
    var tmp = pairs[i].split('=');
    if (tmp[0] != 'mode') newQuery += pairs[i] + '&';
  }
  window.location = '?mode=default&' + newQuery + '#charts';
}

function deleteSettings(setting) {
  var bc_QueryString = new String(document.location.search).substring(1);
  var pairs = bc_QueryString.split('&');
  var newQuery = '&';
  for (var i = 0; i < pairs.length; i++) {
    var tmp = pairs[i].split('=');
    if (tmp[0] != 'mode' && tmp[0] != 'setting') newQuery += pairs[i] + '&';
  }
  newQuery += 'setting=' + setting + '&';
  window.location = '?mode=delete&' + newQuery + '#charts';
}

function changeLocation(loc) {
  if (loc != 'choose') window.location = loc + '#charts';
}

let SUBNAV_SELECTOR = '.list-group.vertical > a:not(.true-link)';
let MOBILE_SUBNAV_SELECTOR =
  '#ticker-page-mobile-nav ul > li a:not(.true-link)';

function etfHandleHash() {
  // reusing extractHash from TableModule to always get the first element of a hash
  etfSelectTab(extractHash().table, false);
}

function etfHashOrDefault(hash) {
  let TABLE_TO_TAB = {
    '#etf-holdings': '#holdings'
  };
  var result = { hash: hash };
  var tableHash = TABLE_TO_TAB[result.hash];
  if (tableHash) {
    result = { tableHash: hash, hash: tableHash };
  }
  result.$link = etfTabLink(result.hash);
  if (result.$link.length == 0) {
    result = etfFirstTab();
  }
  return result;
}

function etfTabLink(hash) {
  return $(SUBNAV_SELECTOR + '[href="' + hash + '"]');
}

function etfFirstTab() {
  const subNav = $(SUBNAV_SELECTOR);
  if(subNav.length > 0 ){
    var firstLink = subNav[0];
    return { hash: firstLink.hash, $link: $(firstLink) };
  }
}

function etfSelectTab(hash, refreshAdsAndPageViews) {
  var desktopTab = etfHashOrDefault(hash);
  var $mobileLink = $(
    MOBILE_SUBNAV_SELECTOR + '[href="' + desktopTab.hash + '"]'
  );
  $('#etf-ticker-body > .collapse').each(function(_, elem) {
    var $elem = $(elem);
    if ('#' + elem.id == desktopTab.hash + '_tab') {
      $elem.collapse('show');
      // update history only if there no hash referencing a table
      if (history.pushState && desktopTab.tableHash == null) {
        history.pushState(null, null, desktopTab.hash);
      }
      // render the chart only once
      if (elem.id == 'price-and-volume_tab' && !$('#barchart-iframe').length) {
        url = new URL(window.location);
        symbol = url.pathname.split('/')[2];
        $(
          '<iframe class="resp-iframe" frameborder="0" id="barchart-iframe" scrolling="no" src="https://etfflows.websol.barchart.com/?module=etfDetail&amp;symbol=' + symbol + '"></iframe>'
        ).appendTo('#price-and-volume_tab #barchart');
      }
    } else {
      $elem.collapse('hide');
    }
  });
  // for desktop tabs
  $(SUBNAV_SELECTOR).removeClass('disabled');
  desktopTab.$link.addClass('disabled');
  // for mobile dropdown
  $('#collapse-nav').collapse('hide');
  $('#collapse-trigger').text(desktopTab.$link.text());
  $('#collapse-trigger').append('<span class="fa fa-caret-down"></span>');
  $(MOBILE_SUBNAV_SELECTOR).removeClass('disabled');
  $mobileLink.addClass('disabled');
  if (refreshAdsAndPageViews) {
    // refresh ads
    Mitre.AdRefresher.refresh({
      ad_unit: 'mitre_webpage',
      '!slot_name': ['A1-4', 'A1-6'],
      visible: false,
      delay: false
    });
    // track pageview
    Mitre.Analytics.trackPageview();
  }
}

// subnav hide and show logic
$(function() {
  $(SUBNAV_SELECTOR).on('click', function(e) {
    e.preventDefault();
    etfSelectTab(e.target.hash, true);
  });
});

$(function() {
  $(MOBILE_SUBNAV_SELECTOR).on('click', function(e) {
    e.preventDefault();
    etfSelectTab(e.target.hash, true);
  });
});

// summary / detailed view toggle
