// // add `See more` functionality to the Analyst Report
document.addEventListener('DOMContentLoaded', () => {
  const button = document.getElementById("analyst-see-more");

  if (!button) return;

  button.addEventListener('click', () => {
    const truncated = document.getElementById("truncated-content");
    const full = document.getElementById("full-content");

    if (full.style.display === "none") {
      full.style.display = "block";
      truncated.style.display = "none";
      button.innerText = "See less";
    } else {
      full.style.display = "none";
      truncated.style.display = "block";
      button.innerText = "See more";
    }
  });
});

//Fix Segment Alignment in the Factset Classfication Table
$(function() {
  if ($("#Segment").text().trim().length >= 30) {
    var texts = $("#Segment").text().split(":");
    var text = texts[0] + ":<br>";
    var sub_text = "";
    var sm_text = "";
    if (texts[1].length >= 30) {
      s_text = texts[1];
      var words = s_text.split(" ");
      for (let i = 0; i < words.length; i++) {
        if ((sm_text + words[i]).length < 30) {
          sm_text += words[i] + " ";
        } else {
          sm_text += "<br>";
          sub_text += sm_text;
          sm_text = words[i] + " ";
        }
      }
      sub_text = sm_text == " " ? sub_text : sub_text + sm_text;
    } else {
      sub_text = texts[1];
    }
    text += sub_text;
    var LineCount = (text.match(/<br>/g) || []).length;
    if (LineCount <= 3) {
      document.getElementById("Segment List").style.height = "70px";
    } else {
      document.getElementById("Segment List").style.height = "105px";
    }
  }
});

