    if (!(match && match[1])) { return; } // if cookie not set exit
    r = /mitre_event\=.*?\%7C(\d*?);/;
    match2 = r.exec(document.cookie);
    if (!(match2 && match2[1])) { return; } // if event not set exit
    Mitre.Analytics.trackEvent('Funnel', 'Successful Login', 'member_id: ' + match2[1]);
    document.cookie = 'mitre_event=; expires=Thu, 01 Jan 1970 00:00:01 GMT;'; // delete cookie
